//! Open vSwitch Tools
//!
//! AGENTS.md §4: D-Bus first. D-Bus always. D-Bus only.
//! These tools use the op-openvswitch-daemon via D-Bus instead of CLI subprocesses.

use crate::tool_registry::{Tool, ToolRegistry};
use anyhow::Result;
use async_trait::async_trait;
use simd_json::{json, OwnedValue as Value};
use std::sync::Arc;

pub async fn register_all(registry: &ToolRegistry) -> Result<usize> {
    registry.register(Arc::new(OvsListBridgesTool)).await?;
    registry.register(Arc::new(OvsShowBridgeTool)).await?;
    registry.register(Arc::new(OvsListPortsTool)).await?;
    registry.register(Arc::new(OvsDumpFlowsTool)).await?;
    registry.register(Arc::new(OvsAddBridgeTool)).await?;
    registry.register(Arc::new(OvsDelBridgeTool)).await?;
    registry.register(Arc::new(OvsAddPortTool)).await?;
    registry.register(Arc::new(OvsDelPortTool)).await?;
    registry.register(Arc::new(OvsAddFlowTool)).await?;
    registry.register(Arc::new(OvsDelFlowsTool)).await?;
    Ok(10)
}

macro_rules! ovs_tool {
    ($name:ident, $tool_name:expr, $desc:expr, $schema:expr, $exec:expr) => {
        pub struct $name;

        #[async_trait]
        impl Tool for $name {
            fn name(&self) -> &str { $tool_name }
            fn description(&self) -> &str { $desc }
            fn category(&self) -> &str { "ovs" }
            fn tags(&self) -> Vec<String> { vec!["ovs".into(), "network".into()] }
            fn input_schema(&self) -> Value { $schema }
            async fn execute(&self, input: Value) -> Result<Value> { $exec(input).await }
        }
    };
}

/// Get OVSDB D-Bus client (from op-network rovs_proxy).
/// AGENTS.md: D-Bus first - never use ovs-vsctl/ovs-ofctl CLI.
async fn ovsdb_client() -> Result<op_network::rovs_proxy::OvsdbDbusClient> {
    Ok(op_network::rovs_proxy::OvsdbDbusClient::new())
}

ovs_tool!(OvsListBridgesTool, "ovs_list_bridges", "List all OVS bridges via D-Bus daemon.",
    json!({"type": "object", "properties": {}}),
    |_input: Value| async {
        let client = ovsdb_client().await?;
        let bridges = client.list_bridges().await
            .map_err(|e| anyhow::anyhow!("D-Bus list_bridges failed: {}", e))?;
        Ok(json!({"success": true, "bridges": bridges, "count": bridges.len(), "method": "dbus_native"}))
    }
);

ovs_tool!(OvsShowBridgeTool, "ovs_show_bridge", "Show OVS bridge details via D-Bus daemon.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}}, "required": ["bridge"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let client = ovsdb_client().await?;
        let ports = client.list_bridge_ports(bridge).await
            .map_err(|e| anyhow::anyhow!("D-Bus list_bridge_ports failed: {}", e))?;
        Ok(json!({"success": true, "bridge": bridge, "ports": ports, "method": "dbus_native"}))
    }
);

ovs_tool!(OvsListPortsTool, "ovs_list_ports", "List ports on an OVS bridge via D-Bus daemon.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}}, "required": ["bridge"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let client = ovsdb_client().await?;
        let ports = client.list_bridge_ports(bridge).await
            .map_err(|e| anyhow::anyhow!("D-Bus list_bridge_ports failed: {}", e))?;
        Ok(json!({"success": true, "bridge": bridge, "ports": ports, "count": ports.len(), "method": "dbus_native"}))
    }
);

ovs_tool!(OvsDumpFlowsTool, "ovs_dump_flows", "Dump flows from an OVS bridge via D-Bus daemon (OpenFlow native).",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}}, "required": ["bridge"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        // Use D-Bus daemon's OpenFlow service via JSON-RPC passthrough
        let client = ovsdb_client().await?;
        // Query flows via OVSDB monitoring (native D-Bus)
        let dump = client.dump_db("Open_vSwitch").await
            .map_err(|e| anyhow::anyhow!("D-Bus dump_db failed: {}", e))?;
        // Extract flows from the dump (flows table in OVSDB)
        let flows: Vec<String> = dump.get("tables")
            .and_then(|t| t.get("Flow"))
            .and_then(|f| f.get("rows"))
            .and_then(|r| r.as_array())
            .map(|arr| arr.iter().map(|v| v.to_string()).collect())
            .unwrap_or_default();
        Ok(json!({"success": true, "bridge": bridge, "flows": flows, "count": flows.len(), "method": "dbus_native"}))
    }
);

ovs_tool!(OvsAddBridgeTool, "ovs_add_bridge", "Create an OVS bridge via D-Bus daemon.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}}, "required": ["bridge"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let client = ovsdb_client().await?;
        client.create_bridge(bridge).await
            .map_err(|e| anyhow::anyhow!("D-Bus create_bridge failed: {}", e))?;
        Ok(json!({"success": true, "bridge": bridge, "action": "created", "method": "dbus_native"}))
    }
);

ovs_tool!(OvsDelBridgeTool, "ovs_del_bridge", "Delete an OVS bridge via D-Bus daemon.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}}, "required": ["bridge"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let client = ovsdb_client().await?;
        client.delete_bridge(bridge).await
            .map_err(|e| anyhow::anyhow!("D-Bus delete_bridge failed: {}", e))?;
        Ok(json!({"success": true, "bridge": bridge, "action": "deleted", "method": "dbus_native"}))
    }
);

ovs_tool!(OvsAddPortTool, "ovs_add_port", "Add a port to an OVS bridge via D-Bus daemon.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}, "port": {"type": "string"}}, "required": ["bridge", "port"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let port = input.get("port").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing port"))?;
        let client = ovsdb_client().await?;
        client.add_port(bridge, port).await
            .map_err(|e| anyhow::anyhow!("D-Bus add_port failed: {}", e))?;
        Ok(json!({"success": true, "bridge": bridge, "port": port, "action": "added", "method": "dbus_native"}))
    }
);

ovs_tool!(OvsDelPortTool, "ovs_del_port", "Remove a port from an OVS bridge via D-Bus daemon.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}, "port": {"type": "string"}}, "required": ["bridge", "port"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let port = input.get("port").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing port"))?;
        let client = ovsdb_client().await?;
        client.delete_port(bridge, port).await
            .map_err(|e| anyhow::anyhow!("D-Bus delete_port failed: {}", e))?;
        Ok(json!({"success": true, "bridge": bridge, "port": port, "action": "deleted", "method": "dbus_native"}))
    }
);

ovs_tool!(OvsAddFlowTool, "ovs_add_flow", "Add a flow to an OVS bridge via OpenFlow native protocol.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}, "flow": {"type": "string"}}, "required": ["bridge", "flow"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let flow = input.get("flow").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing flow"))?;
        // Use OpenFlow native client
        let addr: std::net::SocketAddr = "127.0.0.1:6653".parse()
            .map_err(|e| anyhow::anyhow!("Invalid OpenFlow controller address: {}", e))?;
        let mut openflow_client = op_network::OpenFlowClient::connect(addr).await
            .map_err(|e| anyhow::anyhow!("OpenFlow connect failed: {}", e))?;
        // String-based flow rules - currently logs warning, full parsing pending
        openflow_client.add_flow_rule(flow).await;
        Ok(json!({"success": true, "bridge": bridge, "action": "flow_added", "method": "openflow_native", "note": "String-based flow rules use rovs-openflow native protocol; full ovs-ofctl format parsing is pending"}))
    }
);

ovs_tool!(OvsDelFlowsTool, "ovs_del_flows", "Delete flows from an OVS bridge via OpenFlow native protocol.",
    json!({"type": "object", "properties": {"bridge": {"type": "string"}, "match_str": {"type": "string"}}, "required": ["bridge"]}),
    |input: Value| async move {
        let bridge = input.get("bridge").and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("Missing bridge"))?;
        let addr: std::net::SocketAddr = "127.0.0.1:6653".parse()
            .map_err(|e| anyhow::anyhow!("Invalid OpenFlow controller address: {}", e))?;
        let mut openflow_client = op_network::OpenFlowClient::connect(addr).await
            .map_err(|e| anyhow::anyhow!("OpenFlow connect failed: {}", e))?;
        if input.get("match_str").and_then(|v| v.as_str()).is_some() {
            // Match-specific deletion requires OpenFlow protocol support
            return Ok(json!({"success": false, "error": "Match-specific flow deletion not yet implemented - use delete_all_flows instead", "bridge": bridge}));
        }
        openflow_client.delete_all_flows().await
            .map_err(|e| anyhow::anyhow!("OpenFlow delete_all_flows failed: {}", e))?;
        Ok(json!({"success": true, "bridge": bridge, "action": "flows_deleted", "method": "openflow_native"}))
    }
);

//! Pure passthrough D-Bus interfaces for the op-openvswitch-daemon.
//!
//! TWO separate object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → interface `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → interface `org.opdbus.rovs.openflow`
//!
//! The daemon knows NOTHING about bridges, ports, or containers.  It only
//! proxies raw `rovs-jsonrpc` / `rovs-openflow` primitives over D-Bus.
//! Business logic lives in the consuming plugins.

use anyhow::{Context, Result};
use rovs_ovsdb::Client;
use rovs_transport::Address;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{debug, info};
use zbus::interface;

// ── Shared daemon state ───────────────────────────────────────────────────────

/// Global state shared by both D-Bus objects.
#[derive(Clone)]
pub struct DaemonState {
    /// OVSDB JSON-RPC client (rovs_ovsdb).  Lazily initialised on first call.
    pub ovsdb: Arc<Mutex<Option<Client>>>,
    /// OVS Unix-domain socket path.
    pub socket_path: String,
    /// OpenFlow connections: conn_id → VConn.
    pub of_conns: Arc<Mutex<HashMap<u64, rovs_openflow::VConn>>>,
    /// Monotonic connection handle allocator.
    pub next_of_id: Arc<Mutex<u64>>,
}

impl DaemonState {
    pub fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
            of_conns: Arc::new(Mutex::new(HashMap::new())),
            next_of_id: Arc::new(Mutex::new(1)),
        }
    }

    /// Get or create the persistent OVSDB client.
    pub async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;
        if guard.is_none() {
            let client = Client::connect(&format!("unix:{}", self.socket_path))
                .await
                .with_context(|| format!("connect to OVSDB at {}", self.socket_path))?;
            info!("OVSDB client connected to {}", self.socket_path);
            *guard = Some(client);
        }
        Ok(guard)
    }

    /// Allocate a new OpenFlow connection handle id.
    pub async fn alloc_of_id(&self) -> u64 {
        let mut n = self.next_of_id.lock().await;
        let id = *n;
        *n += 1;
        id
    }
}

// ── JSON-RPC object (/org/opdbus/rovs/jsonrpc) ──────────────────────────────

/// D-Bus service proxying raw `rovs-jsonrpc` + `rovs-ovsdb` primitives.
pub struct JsonRpcService {
    state: DaemonState,
}

impl JsonRpcService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.jsonrpc")]
impl JsonRpcService {
    /// Execute a raw OVSDB JSON-RPC `transact`.
    ///
    /// `method` — JSON-RPC method name (always `"transact"` for OVSDB).
    /// `params_json` — JSON-encoded params array (e.g. `["Open_vSwitch", {op:...}]`).
    /// Returns JSON-encoded result.
    async fn transact(&self, method: &str, params_json: &str) -> String {
        debug!("jsonrpc.transact method={} params_len={}", method, params_json.len());

        let mut guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => return json_error(&format!("OVSDB connect failed: {}", e)),
        };
        let client = match guard.as_mut() {
            Some(c) => c,
            None => return json_error("OVSDB client unavailable"),
        };

        // Parse params as serde_json::Value array.
        let params: serde_json::Value = match serde_json::from_str(params_json) {
            Ok(v) => v,
            Err(e) => return json_error(&format!("invalid params JSON: {}", e)),
        };

        // We use the rovs_ovsdb::Client::transact_raw or similar.
        // Since rovs_ovsdb::Client exposes `transact(Value) -> Result<Value>`,
        // we forward directly.
        match client.transact(params).await {
            Ok(result) => match serde_json::to_string(&result) {
                Ok(s) => s,
                Err(e) => json_error(&format!("serialize result failed: {}", e)),
            },
            Err(e) => json_error(&format!("transact failed: {}", e)),
        }
    }

    /// One-way notify (fire-and-forget).
    async fn notify(&self, _method: &str, _params_json: &str) {
        // rovs-jsonrpc notify support — placeholder; most callers use transact.
        debug!("jsonrpc.notify (passthrough stub)");
    }

    /// Return next JSON-RPC request id (monotonic counter).
    async fn next_id(&self) -> u64 {
        // Simplistic id counter.  In full rovs-jsonrpc this is per-connection.
        1
    }

    /// Send raw JSON-RPC message string, return response string.
    async fn send_message(&self, msg: &str) -> String {
        debug!("jsonrpc.send_message len={}", msg.len());
        match serde_json::from_str::<serde_json::Value>(msg) {
            Ok(req) => {
                let mut guard = match self.state.get_ovsdb().await {
                    Ok(g) => g,
                    Err(e) => return json_error(&format!("connect failed: {}", e)),
                };
                let client = match guard.as_mut() {
                    Some(c) => c,
                    None => return json_error("client unavailable"),
                };
                match client.transact(req).await {
                    Ok(r) => serde_json::to_string(&r).unwrap_or_else(|e| json_error(&e.to_string())),
                    Err(e) => json_error(&e.to_string()),
                }
            }
            Err(e) => json_error(&format!("invalid JSON: {}", e)),
        }
    }

    /// Receive raw JSON-RPC message string.
    async fn recv_message(&self) -> String {
        // rovs-jsonrpc recv is async-stream oriented; stub for now.
        String::new()
    }

    /// Poll pending notifications.
    async fn has_pending_notifications(&self) -> bool {
        false
    }

    /// Count pending notifications.
    async fn pending_notification_count(&self) -> u64 {
        0
    }

    /// Pop one notification.
    async fn pop_notification(&self) -> String {
        String::new()
    }

    /// Drain all notifications.
    async fn drain_notifications(&self) -> String {
        "[]".to_string()
    }

    /// Open a new named stream / monitor.
    async fn new_stream(&self, stream: &str) -> String {
        debug!("jsonrpc.new_stream stream={}", stream);
        format!("{{\"stream\":\"{}\"}}", stream)
    }

    /// Daemon + connection status JSON.
    async fn status(&self) -> String {
        let connected = self.state.ovsdb.lock().await.is_some();
        format!(
            "{{\"connected\":{},\"socket_path\":\"{}\",\"version\":\"{}\"}}",
            connected, self.state.socket_path, env!("CARGO_PKG_VERSION")
        )
    }
}

fn json_error(msg: &str) -> String {
    serde_json::json!({"error": msg}).to_string()
}

// ── OpenFlow object (/org/opdbus/rovs/openflow) ─────────────────────────────

/// D-Bus service proxying raw `rovs-openflow` primitives via `rovs_transport::Address`
/// and `rovs_openflow::VConn`.
pub struct OpenFlowService {
    state: DaemonState,
}

impl OpenFlowService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.rovs.openflow")]
impl OpenFlowService {
    /// Connect to a switch at `addr` (e.g. `"tcp:127.0.0.1:6653"`).
    ///
    /// `addr` is parsed by `rovs_transport::Address::from_str` which supports:
    /// - `unix:/path/to/socket`
    /// - `tcp:host:port`
    /// - `ssl:host:port`
    ///
    /// Returns JSON `{"conn_id":N}` or `{"error":"..."}`.
    async fn connect(&self, addr: &str) -> String {
        debug!("openflow.connect addr={}", addr);

        let address = match addr.parse::<Address>() {
            Ok(a) => a,
            Err(e) => return json_error(&format!("bad address: {}", e)),
        };

        match rovs_openflow::VConn::connect(&address).await {
            Ok(vconn) => {
                let id = self.state.alloc_of_id().await;
                self.state.of_conns.lock().await.insert(id, vconn);
                serde_json::json!({"conn_id": id}).to_string()
            }
            Err(e) => json_error(&format!("connect failed: {}", e)),
        }
    }

    /// Return negotiated OpenFlow version JSON.
    async fn version(&self, conn_id: u64) -> String {
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => {
                let ver = vconn.version();
                serde_json::json!({"version": format!("{:?}", ver)}).to_string()
            }
            None => json_error("unknown conn_id"),
        }
    }

    async fn send_flow(&self, conn_id: u64, flow_json: &str) -> String {
        debug!("openflow.send_flow conn_id={} len={}", conn_id, flow_json.len());
        match parse_json_flow(flow_json) {
            Ok(rovs_flow) => {
                let mut conns = self.state.of_conns.lock().await;
                match conns.get_mut(&conn_id) {
                    Some(vconn) => match vconn.send_flow(&rovs_flow).await {
                        Ok(_) => serde_json::json!({"ok": true}).to_string(),
                        Err(e) => json_error(&format!("send_flow failed: {}", e)),
                    },
                    None => json_error("unknown conn_id"),
                }
            }
            Err(e) => json_error(&format!("JSON deserializer error: {}", e)),
        }
    }

    /// Send flow_mod + barrier.
    async fn send_flow_sync(&self, conn_id: u64, flow_json: &str) -> String {
        debug!("openflow.send_flow_sync conn_id={}", conn_id);
        match parse_json_flow(flow_json) {
            Ok(rovs_flow) => {
                let mut conns = self.state.of_conns.lock().await;
                match conns.get_mut(&conn_id) {
                    Some(vconn) => match vconn.send_flow_sync(&rovs_flow).await {
                        Ok(_) => serde_json::json!({"ok": true}).to_string(),
                        Err(e) => json_error(&format!("send_flow_sync failed: {}", e)),
                    },
                    None => json_error("unknown conn_id"),
                }
            }
            Err(e) => json_error(&format!("JSON deserializer error: {}", e)),
        }
    }

    /// Send an echo request and wait for the echo reply.
    async fn echo(&self, conn_id: u64) -> String {
        debug!("openflow.echo conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.echo().await {
                Ok(()) => serde_json::json!({"ok": true}).to_string(),
                Err(e) => json_error(&format!("echo failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Send a barrier request and wait for the barrier reply.
    async fn barrier(&self, conn_id: u64) -> String {
        debug!("openflow.barrier conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.barrier().await {
                Ok(()) => serde_json::json!({"ok": true}).to_string(),
                Err(e) => json_error(&format!("barrier failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Dump all flows from the switch.  Returns a JSON array string per flow.
    async fn dump_flows(&self, conn_id: u64) -> Vec<String> {
        debug!("openflow.dump_flows conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.dump_flows().await {
                Ok(entries) => entries.iter().map(flow_stats_to_json).collect(),
                Err(e) => vec![json_error(&format!("dump_flows failed: {}", e))],
            },
            None => vec![json_error("unknown conn_id")],
        }
    }

    /// Dump flows matching a filter.  `request_json` is a placeholder.
    async fn dump_flows_filtered(&self, conn_id: u64, _request: &str) -> Vec<String> {
        debug!("openflow.dump_flows_filtered conn_id={}", conn_id);
        // TODO: deserialize FlowStatsRequest from JSON, then call vconn.dump_flows_filtered(req)
        self.dump_flows(conn_id).await
    }

    /// Block until a PacketIn message arrives.
    /// Returns JSON with buffer_id, in_port, reason, table_id, cookie, data (hex).
    async fn recv_packet_in(&self, conn_id: u64) -> String {
        debug!("openflow.recv_packet_in conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.recv_packet_in().await {
                Ok(pkt) => packet_in_to_json(&pkt),
                Err(e) => json_error(&format!("recv_packet_in failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Non-blocking try-receive PacketIn.
    async fn try_recv_packet_in(&self, conn_id: u64) -> String {
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.try_recv_packet_in().await {
                Ok(Some(pkt)) => packet_in_to_json(&pkt),
                Ok(None) => String::new(),
                Err(e) => json_error(&format!("try_recv_packet_in failed: {}", e)),
            },
            None => json_error("unknown conn_id"),
        }
    }

    /// Start flow monitor.  `request_json` is a placeholder.
    async fn monitor_flows(&self, conn_id: u64, _request: &str) -> Vec<String> {
        debug!("openflow.monitor_flows conn_id={}", conn_id);
        // TODO: deserialize FlowMonitorRequest from JSON
        Vec::new()
    }

    /// Block until flow updates arrive.
    async fn recv_flow_updates(&self, conn_id: u64) -> Vec<String> {
        debug!("openflow.recv_flow_updates conn_id={}", conn_id);
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(vconn) => match vconn.recv_flow_updates().await {
                Ok(updates) => updates.iter().map(flow_update_to_json).collect(),
                Err(e) => vec![json_error(&format!("recv_flow_updates failed: {}", e))],
            },
            None => vec![json_error("unknown conn_id")],
        }
    }

    /// Send a packet_out.  `packet_out_json` is a placeholder.
    async fn send_packet_out(&self, conn_id: u64, _packet_out_json: &str) -> String {
        debug!("openflow.send_packet_out conn_id={}", conn_id);
        // TODO: deserialize PacketOut from JSON
        let mut conns = self.state.of_conns.lock().await;
        match conns.get_mut(&conn_id) {
            Some(_vconn) => {
                json_error("send_packet_out: JSON→PacketOut deserialiser not yet implemented")
            }
            None => json_error("unknown conn_id"),
        }
    }

    /// Controller status JSON.
    async fn status(&self) -> String {
        let count = self.state.of_conns.lock().await.len();
        format!(
            "{{\"connections\":{},\"version\":\"{}\"}}",
            count,
            env!("CARGO_PKG_VERSION")
        )
    }
}

// ── JSON serializers for rovs-openflow types ──────────────────────────────────

fn flow_stats_to_json(entry: &rovs_openflow::FlowStatsEntry) -> String {
    serde_json::json!({
        "table_id": entry.table_id,
        "duration_sec": entry.duration_sec,
        "duration_nsec": entry.duration_nsec,
        "priority": entry.priority,
        "idle_timeout": entry.idle_timeout,
        "hard_timeout": entry.hard_timeout,
        "flags": entry.flags,
        "cookie": entry.cookie,
        "packet_count": entry.packet_count,
        "byte_count": entry.byte_count,
        "match_fields_hex": bytes_to_hex(&entry.match_fields.encode()),
        "instructions_hex": bytes_to_hex(&entry.instructions),
    })
    .to_string()
}

fn packet_in_to_json(pkt: &rovs_openflow::PacketIn) -> String {
    serde_json::json!({
        "buffer_id": pkt.buffer_id,
        "total_len": pkt.total_len,
        "reason": format!("{:?}", pkt.reason),
        "table_id": pkt.table_id,
        "cookie": pkt.cookie,
        "match_fields_hex": bytes_to_hex(&pkt.match_fields.encode()),
        "data_hex": bytes_to_hex(&pkt.data),
    })
    .to_string()
}

fn flow_update_to_json(update: &rovs_openflow::FlowUpdate) -> String {
    match update {
        rovs_openflow::FlowUpdate::Full(full) => serde_json::json!({
            "type": "Full",
            "event": format!("{:?}", full.event),
            "reason": full.reason,
            "priority": full.priority,
            "idle_timeout": full.idle_timeout,
            "hard_timeout": full.hard_timeout,
            "table_id": full.table_id,
            "cookie": full.cookie,
            "match_fields_hex": bytes_to_hex(&full.match_fields.encode()),
            "actions_hex": bytes_to_hex(&full.actions),
        }),
        rovs_openflow::FlowUpdate::Abbrev { xid } => serde_json::json!({
            "type": "Abbrev",
            "xid": xid,
        }),
    }
    .to_string()
}

/// Simple hex encoder (avoids pulling in the `hex` crate).
fn bytes_to_hex(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(HEX[(b >> 4) as usize] as char);
        s.push(HEX[(b & 0xF) as usize] as char);
    }
    s
}

#[derive(serde::Deserialize, Debug)]
pub struct JsonFlowEntry {
    pub table: u8,
    pub priority: u16,
    pub match_fields: std::collections::HashMap<String, String>,
    pub actions: Vec<JsonFlowAction>,
    pub cookie: Option<u64>,
    #[serde(default)]
    pub idle_timeout: u16,
    #[serde(default)]
    pub hard_timeout: u16,
}

#[derive(serde::Deserialize, Debug)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum JsonFlowAction {
    Output { port: String },
    LoadRegister { register: u8, value: u64 },
    Resubmit { table: u8 },
    SetField { field: String, value: String },
    Drop,
    Normal,
    Controller { max_len: Option<u16> },
    ArpResponder { mac: String, ip: String },
}

fn parse_json_flow(flow_json: &str) -> Result<rovs_openflow::Flow> {
    let entry: JsonFlowEntry = serde_json::from_str(flow_json).context("invalid JsonFlowEntry format")?;

    let mut m = rovs_openflow::Match::new();
    for (k, v) in entry.match_fields {
        match k.as_str() {
            "in_port" => {
                if let Ok(port) = v.parse::<u32>() {
                    m = m.in_port(port);
                }
            }
            "dl_type" => {
                let eth_type = if v.starts_with("0x") {
                    u16::from_str_radix(v.trim_start_matches("0x"), 16).unwrap_or(0)
                } else {
                    v.parse().unwrap_or(0)
                };
                m = m.eth_type(eth_type);
            }
            "dl_vlan" => {
                if let Ok(vlan) = v.parse::<u16>() {
                    m = m.vlan_vid(vlan);
                }
            }
            // Add other matches here as required
            _ => {
                tracing::warn!("Unsupported match field in JSON->Flow map: {}={}", k, v);
            }
        }
    }

    let mut action_list = rovs_openflow::ActionList::new();
    for action in entry.actions {
        match action {
            JsonFlowAction::Output { port } => {
                if port.eq_ignore_ascii_case("LOCAL") {
                    action_list = action_list.output(rovs_openflow::OutputPort::Local);
                } else if port.eq_ignore_ascii_case("NORMAL") {
                    action_list = action_list.output(rovs_openflow::OutputPort::Normal);
                } else if let Ok(p) = port.parse::<u32>() {
                    action_list = action_list.output(rovs_openflow::OutputPort::Port(p));
                } else {
                    tracing::warn!("Invalid numeric port output: {}", port);
                }
            }
            JsonFlowAction::Normal => {
                action_list = action_list.output(rovs_openflow::OutputPort::Normal);
            }
            JsonFlowAction::Drop => {}
            // Other actions could be mapped here.
            _ => {
                tracing::warn!("Unsupported JSON->Flow action: {:?}", action);
            }
        }
    }

    let mut flow = rovs_openflow::Flow::add()
        .priority(entry.priority)
        .match_fields(m)
        .actions(action_list)
        .idle_timeout(entry.idle_timeout)
        .hard_timeout(entry.hard_timeout);

    if let Some(c) = entry.cookie {
        flow = flow.cookie(c);
    }

    // Some rovs_openflow Flow builders support .table_id(u8), we will skip it for now 
    // unless explicitly supported by the FlowAddBuilder. (Usually table_id=0 by default).

    Ok(flow)
}

//! OVSDB Tools - Native JSON-RPC protocol for Open vSwitch
//!
//! These tools communicate directly with OVSDB via JSON-RPC over Unix socket.
//! NO CLI TOOLS (ovs-vsctl, ovs-ofctl) are used.
//!
//! Protocol: RFC 7047 - The Open vSwitch Database Management Protocol
//! Socket: /var/run/openvswitch/db.sock

use anyhow::{Context, Result};
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::UnixStream;
use tracing::{debug, info, warn};

use crate::tool::{BoxedTool, Tool};

/// Default OVSDB socket path
pub const OVSDB_SOCKET: &str = "/var/run/openvswitch/db.sock";

/// OVSDB JSON-RPC client
pub struct OvsdbClient {
    socket_path: String,
}

impl OvsdbClient {
    /// Create new client with default socket
    pub fn new() -> Self {
        Self {
            socket_path: OVSDB_SOCKET.to_string(),
        }
    }

    /// Create with custom socket path
    pub fn with_socket(path: &str) -> Self {
        Self {
            socket_path: path.to_string(),
        }
    }

    /// Send JSON-RPC request and get response
    async fn rpc_call(&self, method: &str, params: Value) -> Result<Value> {
        let stream = UnixStream::connect(&self.socket_path)
            .await
            .context(format!("Failed to connect to OVSDB socket: {}", self.socket_path))?;

        let (reader, mut writer) = stream.into_split();
        let mut reader = BufReader::new(reader);

        // Build JSON-RPC request
        let request = json!({
            "method": method,
            "params": params,
            "id": 1
        });

        let request_str = simd_json::to_string(&request)? + "\n";
        debug!("OVSDB request: {}", request_str.trim());

        writer.write_all(request_str.as_bytes()).await?;
        writer.flush().await?;

        // Read response
        let mut response_str = String::new();
        reader.read_line(&mut response_str).await?;
        debug!("OVSDB response: {}", response_str.trim());

        let response: Value = simd_json::from_str(&response_str)
            .context("Failed to parse OVSDB response")?;

        // Check for error
        if let Some(error) = response.get("error") {
            if !error.is_null() {
                return Err(anyhow::anyhow!("OVSDB error: {}", error));
            }
        }

        Ok(response.get("result").cloned().unwrap_or(Value::Null))
    }

    /// Execute OVSDB transaction
    pub async fn transact(&self, operations: Vec<Value>) -> Result<Value> {
        let params = json!(["Open_vSwitch", operations]);
        self.rpc_call("transact", params).await
    }

    /// List all databases
    pub async fn list_dbs(&self) -> Result<Vec<String>> {
        let result = self.rpc_call("list_dbs", json!([])).await?;
        let dbs: Vec<String> = simd_json::serde::from_owned_value(result)?;
        Ok(dbs)
    }

    /// Get database schema
    pub async fn get_schema(&self, db: &str) -> Result<Value> {
        self.rpc_call("get_schema", json!([db])).await
    }

    /// Create a bridge
    pub async fn create_bridge(&self, name: &str) -> Result<Value> {
        info!("Creating OVS bridge '{}' via OVSDB JSON-RPC", name);

        // First, get the Open_vSwitch row UUID
        let select_ovs = json!({
            "op": "select",
            "table": "Open_vSwitch",
            "where": []
        });

        let result = self.transact(vec![select_ovs]).await?;
        let ovs_uuid = result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .and_then(|row| row.get("_uuid"))
            .and_then(|uuid| uuid.get(1))
            .and_then(|u| u.as_str())
            .ok_or_else(|| anyhow::anyhow!("Could not find Open_vSwitch row"))?;

        // Insert bridge and update Open_vSwitch.bridges
        let operations = vec![
            // Insert new bridge
            json!({
                "op": "insert",
                "table": "Bridge",
                "row": {
                    "name": name,
                    "protocols": ["set", ["OpenFlow10", "OpenFlow13"]]
                },
                "uuid-name": "new_bridge"
            }),
            // Add bridge to Open_vSwitch.bridges set
            json!({
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [["_uuid", "==", ["uuid", ovs_uuid]]],
                "mutations": [
                    ["bridges", "insert", ["named-uuid", "new_bridge"]]
                ]
            }),
        ];

        self.transact(operations).await
    }

    /// Delete a bridge
    pub async fn delete_bridge(&self, name: &str) -> Result<Value> {
        info!("Deleting OVS bridge '{}' via OVSDB JSON-RPC", name);

        // Get bridge UUID
        let select_bridge = json!({
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", name]]
        });

        let result = self.transact(vec![select_bridge]).await?;
        let bridge_uuid = result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .and_then(|row| row.get("_uuid"))
            .and_then(|uuid| uuid.get(1))
            .and_then(|u| u.as_str())
            .ok_or_else(|| anyhow::anyhow!("Bridge '{}' not found", name))?;

        // Get Open_vSwitch UUID
        let select_ovs = json!({
            "op": "select",
            "table": "Open_vSwitch",
            "where": []
        });

        let result = self.transact(vec![select_ovs]).await?;
        let ovs_uuid = result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .and_then(|row| row.get("_uuid"))
            .and_then(|uuid| uuid.get(1))
            .and_then(|u| u.as_str())
            .ok_or_else(|| anyhow::anyhow!("Could not find Open_vSwitch row"))?;

        // Remove bridge from Open_vSwitch and delete it
        let operations = vec![
            json!({
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [["_uuid", "==", ["uuid", ovs_uuid]]],
                "mutations": [
                    ["bridges", "delete", ["uuid", bridge_uuid]]
                ]
            }),
            json!({
                "op": "delete",
                "table": "Bridge",
                "where": [["name", "==", name]]
            }),
        ];

        self.transact(operations).await
    }

    /// List all bridges
    pub async fn list_bridges(&self) -> Result<Vec<String>> {
        let select = json!({
            "op": "select",
            "table": "Bridge",
            "where": [],
            "columns": ["name"]
        });

        let result = self.transact(vec![select]).await?;
        let mut bridges = Vec::new();

        if let Some(rows) = result.get(0).and_then(|r| r.get("rows")).and_then(|r| r.as_array()) {
            for row in rows {
                if let Some(name) = row.get("name").and_then(|n| n.as_str()) {
                    bridges.push(name.to_string());
                }
            }
        }

        Ok(bridges)
    }

    /// Add port to bridge
    pub async fn add_port(&self, bridge: &str, port: &str) -> Result<Value> {
        info!("Adding port '{}' to bridge '{}' via OVSDB JSON-RPC", port, bridge);

        // Get bridge UUID
        let select_bridge = json!({
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", bridge]]
        });

        let result = self.transact(vec![select_bridge]).await?;
        let bridge_uuid = result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .and_then(|row| row.get("_uuid"))
            .and_then(|uuid| uuid.get(1))
            .and_then(|u| u.as_str())
            .ok_or_else(|| anyhow::anyhow!("Bridge '{}' not found", bridge))?;

        let operations = vec![
            // Create interface
            json!({
                "op": "insert",
                "table": "Interface",
                "row": {
                    "name": port,
                    "type": ""
                },
                "uuid-name": "new_interface"
            }),
            // Create port with interface
            json!({
                "op": "insert",
                "table": "Port",
                "row": {
                    "name": port,
                    "interfaces": ["named-uuid", "new_interface"]
                },
                "uuid-name": "new_port"
            }),
            // Add port to bridge
            json!({
                "op": "mutate",
                "table": "Bridge",
                "where": [["_uuid", "==", ["uuid", bridge_uuid]]],
                "mutations": [
                    ["ports", "insert", ["named-uuid", "new_port"]]
                ]
            }),
        ];

        self.transact(operations).await
    }

    /// Delete port from bridge
    pub async fn delete_port(&self, bridge: &str, port: &str) -> Result<Value> {
        info!("Deleting port '{}' from bridge '{}' via OVSDB JSON-RPC", port, bridge);

        // Get port UUID
        let select_port = json!({
            "op": "select",
            "table": "Port",
            "where": [["name", "==", port]]
        });

        let result = self.transact(vec![select_port]).await?;
        let port_uuid = result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .and_then(|row| row.get("_uuid"))
            .and_then(|uuid| uuid.get(1))
            .and_then(|u| u.as_str())
            .ok_or_else(|| anyhow::anyhow!("Port '{}' not found", port))?;

        // Get bridge UUID
        let select_bridge = json!({
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", bridge]]
        });

        let result = self.transact(vec![select_bridge]).await?;
        let bridge_uuid = result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .and_then(|row| row.get("_uuid"))
            .and_then(|uuid| uuid.get(1))
            .and_then(|u| u.as_str())
            .ok_or_else(|| anyhow::anyhow!("Bridge '{}' not found", bridge))?;

        let operations = vec![
            // Remove port from bridge
            json!({
                "op": "mutate",
                "table": "Bridge",
                "where": [["_uuid", "==", ["uuid", bridge_uuid]]],
                "mutations": [
                    ["ports", "delete", ["uuid", port_uuid]]
                ]
            }),
            // Delete port (interface is deleted by cascade)
            json!({
                "op": "delete",
                "table": "Port",
                "where": [["name", "==", port]]
            }),
        ];

        self.transact(operations).await
    }

    /// List ports on a bridge
    pub async fn list_ports(&self, bridge: &str) -> Result<Vec<String>> {
        let select = json!({
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", bridge]],
            "columns": ["ports"]
        });

        let result = self.transact(vec![select]).await?;
        let mut ports = Vec::new();

        // Get port UUIDs from bridge
        let port_uuids = result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .and_then(|row| row.get("ports"));

        if let Some(port_refs) = port_uuids {
            // port_refs is either ["set", [...]] or ["uuid", "..."]
            let uuids: Vec<&str> = if let Some(arr) = port_refs.get(1).and_then(|v| v.as_array()) {
                arr.iter()
                    .filter_map(|u| u.get(1).and_then(|v| v.as_str()))
                    .collect()
            } else if let Some(uuid) = port_refs.get(1).and_then(|v| v.as_str()) {
                vec![uuid]
            } else {
                vec![]
            };

            // Get port names
            for uuid in uuids {
                let select_port = json!({
                    "op": "select",
                    "table": "Port",
                    "where": [["_uuid", "==", ["uuid", uuid]]],
                    "columns": ["name"]
                });

                if let Ok(result) = self.transact(vec![select_port]).await {
                    if let Some(name) = result
                        .get(0)
                        .and_then(|r| r.get("rows"))
                        .and_then(|rows| rows.get(0))
                        .and_then(|row| row.get("name"))
                        .and_then(|n| n.as_str())
                    {
                        ports.push(name.to_string());
                    }
                }
            }
        }

        Ok(ports)
    }

    /// Get bridge info
    pub async fn get_bridge(&self, name: &str) -> Result<Value> {
        let select = json!({
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", name]]
        });

        let result = self.transact(vec![select]).await?;

        result
            .get(0)
            .and_then(|r| r.get("rows"))
            .and_then(|rows| rows.get(0))
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("Bridge '{}' not found", name))
    }
}

impl Default for OvsdbClient {
    fn default() -> Self {
        Self::new()
    }
}

