            zbus::zvariant::OwnedObjectPath, u32, String, zbus::zvariant::OwnedObjectPath,
        )> = proxy.call("ListUnits", &()).await?;

        let filtered_units: Vec<Value> = units
            .into_iter()
            .filter(|(name, _, _, active_state, _, _, _, _, _, _)| {
