/// Tool: Get Bridge Info
pub struct OvsGetBridgeTool;

#[async_trait]
impl Tool for OvsGetBridgeTool {
    fn name(&self) -> &str {
        "ovs_get_bridge"
    }

    fn description(&self) -> &str {
        "Get detailed information about an Open vSwitch bridge via D-Bus daemon (OVSDB)."
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name of the bridge"
                }
            },
            "required": ["name"]
        })
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let name = input
            .get("name")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing required parameter: name"))?;

        let client = ovsdb_client().await?;

        // get_bridge_info returns a JSON string
        let info_str = client.get_bridge_info(name).await
            .map_err(|e| anyhow::anyhow!("D-Bus get_bridge_info failed: {}", e))?;
        let info: Value = simd_json::from_str(&info_str)
            .unwrap_or_else(|_| json!({"raw": info_str}));

        let ports = client.list_bridge_ports(name).await
            .unwrap_or_default();

        Ok(json!({
            "success": true,
            "operation": "get_bridge",
            "bridge": name,
            "info": info,
            "ports": ports,
            "protocol": "D-Bus → op-openvswitch-daemon → OVSDB",
            "method": "dbus_native"
        }))
    }

    fn category(&self) -> &str {
        "network"
    }

    fn tags(&self) -> Vec<String> {
        vec!["ovs".to_string(), "bridge".to_string(), "ovsdb".to_string()]
    }
}

