    vec![
        Arc::new(OvsCreateBridgeTool),
        Arc::new(OvsDeleteBridgeTool),
        Arc::new(OvsListBridgesTool),
        Arc::new(OvsAddPortTool),
        Arc::new(OvsDeletePortTool),
